urllib3.util.ssl_match_hostname.match_ho:
def match_hostname(cert, hostname):
    """Verify that *cert* (in decoded format as returned by
    SSLSocket.getpeercert()) matches the *hostname*.  RFC 2818 and RFC 6125
    rules are followed, but IP addresses are not accepted for *hostname*.

    CertificateError is raised on failure. On success, the function
    returns nothing.
    """
    if not cert:
        raise ValueError('empty or no certificate, match_hostname needs a SSL socket or SSL context with either CERT_OPTIONAL or CERT_REQUIRED')
    try:
        host_ip = ipaddress.ip_address(_to_unicode(hostname))
    except (UnicodeError, ValueError):
        host_ip = None
    except AttributeError:
        if ipaddress is None:
            host_ip = None
        else:
            raise
    dnsnames = []
    san = cert.get('subjectAltName', ())
    for (key, value) in san:
        if key == 'DNS':
            if (host_ip is None and _dnsname_match(value, hostname)):
                return
            dnsnames.append(value)
        elif key == 'IP Address':
            if (host_ip is not None and _ipaddress_match(value, host_ip)):
                return
            dnsnames.append(value)
    if not dnsnames:
        for sub in cert.get('subject', ()):
            for (key, value) in sub:
                if key == 'commonName':
                    if _dnsname_match(value, hostname):
                        return
                    dnsnames.append(value)
    if len(dnsnames) > 1:
        raise CertificateError("hostname %r doesn't match either of %s" % (hostname, ', '.join(map(repr, dnsnames))))
    elif len(dnsnames) == 1:
        raise CertificateError("hostname %r doesn't match %r" % (hostname, dnsnames[0]))
    else:
        raise CertificateError('no appropriate commonName or subjectAltName fields were found')

urllib3.util.ssl_match_hostname._to_unic:
def _to_unicode(obj):
    if (isinstance(obj, str) and sys.version_info < (3, )):
        obj = unicode(obj, encoding='ascii', errors='strict')
    return obj

urllib3.util.ssl_match_hostname._dnsname:
def _dnsname_match(dn, hostname, max_wildcards=1):
    """Matching according to RFC 6125, section 6.4.3

    http://tools.ietf.org/html/rfc6125#section-6.4.3
    """
    pats = []
    if not dn:
        return False
    parts = dn.split('.')
    leftmost = parts[0]
    remainder = parts[1:]
    wildcards = leftmost.count('*')
    if wildcards > max_wildcards:
        raise CertificateError('too many wildcards in certificate DNS name: ' + repr(dn))
    if not wildcards:
        return dn.lower() == hostname.lower()
    if leftmost == '*':
        pats.append('[^.]+')
    elif (leftmost.startswith('xn--') or hostname.startswith('xn--')):
        pats.append(re.escape(leftmost))
    else:
        pats.append(re.escape(leftmost).replace('\\*', '[^.]*'))
    for frag in remainder:
        pats.append(re.escape(frag))
    pat = re.compile('\\A' + '\\.'.join(pats) + '\\Z', re.IGNORECASE)
    return pat.match(hostname)

urllib3.connection._match_hostname:
def _match_hostname(cert, asserted_hostname):
    stripped_hostname = asserted_hostname.strip('u[]')
    if is_ipaddress(stripped_hostname):
        asserted_hostname = stripped_hostname
    try:
        match_hostname(cert, asserted_hostname)
    except CertificateError as e:
        log.warning('Certificate did not match expected hostname: %s. Certificate: %s', asserted_hostname, cert)
        e._peer_cert = cert
        raise

urllib3.util.url.parse_url:
def parse_url(url):
    """
    Given a url, return a parsed :class:`.Url` namedtuple. Best-effort is
    performed to parse incomplete urls. Fields not provided will be None.
    This parser is RFC 3986 and RFC 6874 compliant.

    The parser logic and helper functions are based heavily on
    work done in the ``rfc3986`` module.

    :param str url: URL to parse into a :class:`.Url` namedtuple.

    Partly backwards-compatible with :mod:`urlparse`.

    Example::

        >>> parse_url('http://google.com/mail/')
        Url(scheme='http', host='google.com', port=None, path='/mail/', ...)
        >>> parse_url('google.com:80')
        Url(scheme=None, host='google.com', port=80, path=None, ...)
        >>> parse_url('/foo?bar')
        Url(scheme=None, host=None, port=None, path='/foo', query='bar', ...)
    """
    if not url:
        return Url()
    source_url = url
    if not SCHEME_RE.search(url):
        url = '//' + url
    try:
        (scheme, authority, path, query, fragment) = URI_RE.match(url).groups()
        normalize_uri = (scheme is None or scheme.lower() in NORMALIZABLE_SCHEMES)
        if scheme:
            scheme = scheme.lower()
        if authority:
            (auth, _, host_port) = authority.rpartition('@')
            auth = (auth or None)
            (host, port) = _HOST_PORT_RE.match(host_port).groups()
            if (auth and normalize_uri):
                auth = _encode_invalid_chars(auth, USERINFO_CHARS)
            if port == '':
                port = None
        else:
            (auth, host, port) = (None, None, None)
        if port is not None:
            port = int(port)
            if not 0 <= port <= 65535:
                raise LocationParseError(url)
        host = _normalize_host(host, scheme)
        if (normalize_uri and path):
            path = _remove_path_dot_segments(path)
            path = _encode_invalid_chars(path, PATH_CHARS)
        if (normalize_uri and query):
            query = _encode_invalid_chars(query, QUERY_CHARS)
        if (normalize_uri and fragment):
            fragment = _encode_invalid_chars(fragment, FRAGMENT_CHARS)
    except (ValueError, AttributeError):
        return six.raise_from(LocationParseError(source_url), None)
    if not path:
        if (query is not None or fragment is not None):
            path = ''
        else:
            path = None
    if isinstance(url, six.text_type):
        ensure_func = six.ensure_text
    else:
        ensure_func = six.ensure_str

    def ensure_type(x):
        return (x if x is None else ensure_func(x))
    return Url(scheme=ensure_type(scheme), auth=ensure_type(auth), host=ensure_type(host), port=port, path=ensure_type(path), query=ensure_type(query), fragment=ensure_type(fragment))

requests.utils.prepend_scheme_if_needed:
def prepend_scheme_if_needed(url, new_scheme):
    """Given a URL that may or may not have a scheme, prepend the given scheme.
    Does not replace a present scheme with the one provided as an argument.

    :rtype: str
    """
    parsed = parse_url(url)
    (scheme, auth, host, port, path, query, fragment) = parsed
    netloc = parsed.netloc
    if not netloc:
        (netloc, path) = (path, netloc)
    if auth:
        netloc = '@'.join([auth, netloc])
    if scheme is None:
        scheme = new_scheme
    if path is None:
        path = ''
    return urlunparse((scheme, netloc, path, '', query, fragment))

urllib3.util.url._remove_path_dot_segmen:
def _remove_path_dot_segments(path):
    segments = path.split('/')
    output = []
    for segment in segments:
        if segment == '.':
            continue
        elif segment != '..':
            output.append(segment)
        elif output:
            output.pop()
    if (path.startswith('/') and ((not output or output[0]))):
        output.insert(0, '')
    if path.endswith(('/.', '/..')):
        output.append('')
    return '/'.join(output)

urllib3.util.url._normalize_host:
def _normalize_host(host, scheme):
    if host:
        if isinstance(host, six.binary_type):
            host = six.ensure_str(host)
        if scheme in NORMALIZABLE_SCHEMES:
            is_ipv6 = IPV6_ADDRZ_RE.match(host)
            if is_ipv6:
                match = ZONE_ID_RE.search(host)
                if match:
                    (start, end) = match.span(1)
                    zone_id = host[start:end]
                    if (zone_id.startswith('%25') and zone_id != '%25'):
                        zone_id = zone_id[3:]
                    else:
                        zone_id = zone_id[1:]
                    zone_id = '%' + _encode_invalid_chars(zone_id, UNRESERVED_CHARS)
                    return host[:start].lower() + zone_id + host[end:]
                else:
                    return host.lower()
            elif not IPV4_RE.match(host):
                return six.ensure_str(b'.'.join([_idna_encode(label) for label in host.split('.')]))
    return host

urllib3.packages.six.ensure_str:
def ensure_str(s, encoding='utf-8', errors='strict'):
    """Coerce *s* to `str`.

    For Python 2:
      - `unicode` -> encoded to `str`
      - `str` -> `str`

    For Python 3:
      - `str` -> `str`
      - `bytes` -> decoded to `str`
    """
    if type(s) is str:
        return s
    if (PY2 and isinstance(s, text_type)):
        return s.encode(encoding, errors)
    elif (PY3 and isinstance(s, binary_type)):
        return s.decode(encoding, errors)
    elif not isinstance(s, (text_type, binary_type)):
        raise TypeError("not expecting type '%s'" % type(s))
    return s

urllib3.util.url._idna_encode:
def _idna_encode(name):
    if (name and any([ord(x) > 128 for x in name])):
        try:
            import idna
        except ImportError:
            six.raise_from(LocationParseError("Unable to parse URL without the 'idna' module"), None)
        try:
            return idna.encode(name.lower(), strict=True, std3_rules=True)
        except idna.IDNAError:
            six.raise_from(LocationParseError("Name '%s' is not a valid IDNA label" % name), None)
    return name.lower().encode('ascii')

charset_normalizer.utils.is_accentuated:
@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_accentuated(character: str) -> bool:
    try:
        description: str = unicodedata.name(character)
    except ValueError:
        return False
    return ('WITH GRAVE' in description or 'WITH ACUTE' in description or 'WITH CEDILLA' in description or 'WITH DIAERESIS' in description or 'WITH CIRCUMFLEX' in description or 'WITH TILDE' in description)

charset_normalizer.utils.is_latin:
@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_latin(character: str) -> bool:
    try:
        description: str = unicodedata.name(character)
    except ValueError:
        return False
    return 'LATIN' in description

charset_normalizer.cd.get_target_feature:
@lru_cache(maxsize=LANGUAGE_SUPPORTED_COUNT)
def get_target_features(language: str) -> Tuple[(bool, bool)]:
    """
    Determine main aspects from a supported language if it contains accents and if is pure Latin.
    """
    target_have_accents: bool = False
    target_pure_latin: bool = True
    for character in FREQUENCIES[language]:
        if (not target_have_accents and is_accentuated(character)):
            target_have_accents = True
        if (target_pure_latin and is_latin(character) is False):
            target_pure_latin = False
    return (target_have_accents, target_pure_latin)

charset_normalizer.cd.unicode_range_lang:
def unicode_range_languages(primary_range: str) -> List[str]:
    """
    Return inferred languages used with a unicode range.
    """
    languages: List[str] = []
    for (language, characters) in FREQUENCIES.items():
        for character in characters:
            if unicode_range(character) == primary_range:
                languages.append(language)
                break
    return languages
